def agenda(
    calendar=None, days=None, timezone=None, today=None, tomorrow=None, week=None, test=False
):
    """
    [Helper] Show upcoming events across all calendars

    Options:

    * ``calendar`` (optional value): Filter to specific calendar name or ID
    * ``days`` (optional value): Number of days ahead to show
    * ``timezone`` (optional value): IANA timezone override (e.g. America/Denver). Defaults to Google account timezone.
    * ``today`` (optional flag): Show today's events
    * ``tomorrow`` (optional flag): Show tomorrow's events
    * ``week`` (optional flag): Show this week's events

    CLI Example:

    .. code-block:: bash

        salt '*' gsuite_calendar.agenda
    """
    return _gws.run_helper(
        __opts__,
        __pillar__,
        "calendar",
        "+agenda",
        flags={
            "calendar": calendar,
            "days": days,
            "timezone": timezone,
        },
        switches={
            "today": today,
            "tomorrow": tomorrow,
            "week": week,
        },
        test=test,
    )


def insert(
    end,
    start,
    summary,
    attendee=None,
    calendar=None,
    description=None,
    location=None,
    meet=None,
    test=False,
):
    """
    [Helper] create a new event

    Options:

    * ``end`` (required value): End time (ISO 8601)
    * ``start`` (required value): Start time (ISO 8601, e.g., 2024-01-01T10:00:00Z)
    * ``summary`` (required value): Event summary/title
    * ``attendee`` (optional value): Attendee email (can be used multiple times)
    * ``calendar`` (optional value): Calendar ID (default: primary) [default: primary]
    * ``description`` (optional value): Event description/body
    * ``location`` (optional value): Event location
    * ``meet`` (optional flag): Add a Google Meet video conference link

    CLI Example:

    .. code-block:: bash

        salt '*' gsuite_calendar.insert
    """
    return _gws.run_helper(
        __opts__,
        __pillar__,
        "calendar",
        "+insert",
        flags={
            "end": end,
            "start": start,
            "summary": summary,
            "attendee": attendee,
            "calendar": calendar,
            "description": description,
            "location": location,
        },
        switches={
            "meet": meet,
        },
        test=test,
    )
